-- ============================================================
-- 22_wuxing_wiki.sql
-- 五行穿搭百科 + 周易文化知识库
-- 从静态 JSON 迁移到 PostgreSQL，支持动态内容管理
-- ============================================================

-- 1. 创建百科知识表
CREATE TABLE IF NOT EXISTS wuxing_wiki (
    id            SERIAL PRIMARY KEY,
    element       VARCHAR(10)  NOT NULL DEFAULT '通用',   -- 木/火/土/金/水/通用
    category      VARCHAR(50)  NOT NULL,                   -- 颜色搭配/材质推荐/周易基础/八卦入门/...
    content_type  VARCHAR(20)  NOT NULL DEFAULT 'wuxing',  -- wuxing/zhouyi
    difficulty    VARCHAR(10)  NOT NULL DEFAULT '入门',     -- 入门/进阶/精通
    title         VARCHAR(200) NOT NULL,
    content       TEXT         NOT NULL,
    tags          JSONB        DEFAULT '[]'::jsonb,
    source        VARCHAR(200) DEFAULT NULL,               -- 知识来源，如"《周易》""《黄帝内经》"
    sort_order    INT          DEFAULT 0,
    is_published  BOOLEAN      DEFAULT TRUE,
    created_at    TIMESTAMPTZ  DEFAULT NOW(),
    updated_at    TIMESTAMPTZ  DEFAULT NOW()
);

-- 索引
CREATE INDEX IF NOT EXISTS idx_wuxing_wiki_content_type ON wuxing_wiki(content_type);
CREATE INDEX IF NOT EXISTS idx_wuxing_wiki_element ON wuxing_wiki(element);
CREATE INDEX IF NOT EXISTS idx_wuxing_wiki_category ON wuxing_wiki(category);
CREATE INDEX IF NOT EXISTS idx_wuxing_wiki_difficulty ON wuxing_wiki(difficulty);
CREATE INDEX IF NOT EXISTS idx_wuxing_wiki_published ON wuxing_wiki(is_published);

