INSERT INTO wuxing_wiki (id, element, category, content_type, difficulty, title, content, tags, sort_order) VALUES
(1, '木', '颜色搭配', 'wuxing', '入门', '木属性穿搭色彩指南', '木属性人适合绿色系、青色系服饰。春季穿浅绿显生机，秋冬可选墨绿、橄榄绿增添沉稳感。搭配建议：绿色上衣配米白裤装，木土相生和谐自然。避免大面积白色，金克木会削弱气场。日常可用薄荷绿T恤搭配卡其色休闲裤，清新又得体。', '["颜色","搭配","春季"]', 1),
(2, '木', '材质推荐', 'wuxing', '入门', '木属性面料选择指南', '木属性与天然植物纤维最为契合。棉麻面料是首选，透气亲肤且呼应木的自然属性。春夏推荐亚麻衬衫、纯棉T恤，秋冬可选灯芯绒和粗花呢，保留质朴质感。竹纤维面料也是上佳之选，兼具环保与舒适。避免过多化纤材质，人造纤维与木属性相悖，易显浮躁。', '["材质","面料","棉麻"]', 2),
(3, '木', '适合场景', 'wuxing', '入门', '木属性穿搭最佳场景', '木属性穿搭最适合户外活动、创意工作坊和文艺聚会。公园野餐穿浅绿棉麻套装，自然融入环境；艺术展览选青色长衫配木质配饰，彰显文人气质。创意行业的工作场合也很适合，一件橄榄绿工装夹克既专业又有个性。植物园、茶会、读书会等场景穿木属性配色尤为应景。', '["场景","户外","创意"]', 3),
(4, '木', '忌讳搭配', 'wuxing', '进阶', '木属性穿搭三大禁忌', '第一忌：大面积纯白色系，白色属金，金克木压制气场，如需白色建议小面积点缀。第二忌：全身金属配饰过多，金银首饰不宜超过两件，否则破坏木属性的温和感。第三忌：过于锋利的剪裁风格，尖锐棱角的设计与木的柔韧生长特质相冲突。建议用圆润线条的服装廓形来呼应木属性。', '["禁忌","忌讳","金克木"]', 4),
(5, '木', '历史趣闻', 'wuxing', '精通', '青色衣裳与木的千年渊源', '古人以青色为东方之色，对应木属性与春天。《诗经》中"青青子衿"描绘的便是学子身着青衣的儒雅形象。汉代五德终始说中，木德之朝尚青色，天子春祭亦着青袍。宋代文人崇尚自然，青衫成为读书人标配，苏东坡便有"竹杖芒鞋轻胜马，谁怕？一蓑烟雨任平生"的洒脱。青色与木的关联，贯穿了整个中国服饰文化史。', '["文化","历史","青色"]', 5),
(6, '火', '颜色搭配', 'wuxing', '入门', '火属性穿搭色彩指南', '火属性人适合红色系、紫色系和橙色系服饰。正红色气场强大适合正式场合，酒红色沉稳优雅适合秋冬日常，橙色系活力十足适合运动休闲。搭配建议：红色上衣配黑色下装，水火既济刚柔并济；或用粉色搭配米色，热情中带着温柔。夏季可选珊瑚红，冬季推荐勃艮第酒红。', '["颜色","搭配","红色"]', 6),
(7, '火', '材质推荐', 'wuxing', '入门', '火属性面料选择指南', '火属性适合光泽感强、质感细腻的面料。丝绒和缎面能反射光线，营造华丽热情的视觉效果。夏季推荐真丝衬衫，光泽柔美又透气凉爽；秋冬可选丝绒西装外套或针织毛衣，温暖中透着高级感。雪纺面料也适合火属性，轻盈飘逸如跳动的火焰。粗犷的牛仔布和厚重棉布则不太匹配。', '["材质","面料","丝绒"]', 7),
(8, '火', '适合场景', 'wuxing', '入门', '火属性穿搭最佳场景', '火属性穿搭在派对聚会、舞台表演和商务演讲中最能发挥魅力。晚宴场合一袭红色礼服气场全开；创业路演穿酒红色西装传递自信与热情；音乐节上橙色系穿搭让你成为人群焦点。约会场景也很适合，暖色调服饰自带亲和力。火锅聚餐、庆典活动、年终晚会等热闹场合都是火属性穿搭的主场。', '["场景","派对","商务"]', 8),
(9, '火', '忌讳搭配', 'wuxing', '进阶', '火属性穿搭三大禁忌', '第一忌：大面积深黑色穿搭，黑色属水，水克火直接浇灭热情气场。如必须穿黑色，建议用红色配饰点睛。第二忌：全身蓝色系，蓝色同样属水，火属性人穿蓝色容易显得无精打采。第三忌：过于厚重的叠穿风格，火需要"呼吸"和"燃烧"，层层包裹的穿搭会压制火属性的活力与张力。', '["禁忌","忌讳","水克火"]', 9),
(10, '火', '历史趣闻', 'wuxing', '精通', '朱红华服与火德王朝', '周朝尚火德，以赤色为尊，天子冕服以朱红为主色。《礼记》记载"周人尚赤"，红色被视为最尊贵的颜色。明代亦尚火德，朱元璋以"朱"为国姓，皇宫大门漆朱红色，官员朝服也以红色为贵。民间婚嫁穿红袍、盖红盖头的习俗延续至今，都源于火属性与红色的深厚渊源。火与红的文化基因，深刻影响了中国人的审美。', '["文化","历史","朱红"]', 10),
(11, '土', '颜色搭配', 'wuxing', '入门', '土属性穿搭色彩指南', '土属性人适合黄色系、棕色系和大地色系服饰。驼色大衣是秋冬经典单品，温暖又有包容感；卡其色休闲裤百搭不挑人；姜黄色毛衣提亮肤色又不失稳重。搭配建议：米色衬衫配深棕色西裤，大地色系层次感丰富；或用暖黄色围巾为素色穿搭增添亮点。土属性穿搭的核心是和谐与包容。', '["颜色","搭配","大地色"]', 11),
(12, '土', '材质推荐', 'wuxing', '入门', '土属性面料选择指南', '土属性适合质感厚实、触感温润的面料。羊毛和羊绒是秋冬首选，柔软保暖象征大地的包容。棉质面料四季皆宜，朴实自然呼应土的厚重本质。皮革制品也很契合，皮质外套和包袋增添稳重感。粗花呢和灯芯绒也是不错的选择，肌理丰富的面料能体现土属性的踏实感。避免过于轻薄透透的面料。', '["材质","面料","羊毛"]', 12),
(13, '土', '适合场景', 'wuxing', '入门', '土属性穿搭最佳场景', '土属性穿搭最适合商务会议、家庭聚餐和日常通勤。大地色系的穿搭给人可靠、稳重的好印象，面试和商务谈判尤其加分。周末家庭聚会穿驼色针织衫温馨得体；日常通勤选卡其色风衣百搭又实用。农业体验、陶艺工坊、户外徒步等接地气的活动也很适合土属性穿搭，与大地亲近呼应本源。', '["场景","商务","日常"]', 13),
(14, '土', '忌讳搭配', 'wuxing', '进阶', '土属性穿搭三大禁忌', '第一忌：大面积鲜艳绿色，绿色属木，木克土会压制土属性的稳重气场。小面积绿色配饰尚可，但全身绿色应避免。第二忌：过于前卫的穿搭风格，土属性讲究踏实包容，过于标新立异的造型反而违和。第三忌：颜色搭配过于跳跃，荧光色、撞色穿搭与土属性的沉稳基调不符，建议保持同色系或邻近色搭配。', '["禁忌","忌讳","木克土"]', 14),
(15, '土', '历史趣闻', 'wuxing', '精通', '黄袍加身与土德至尊', '黄色在中国文化中地位崇高，五行属土居中央，统御四方。自隋唐起，黄色逐渐成为皇室专用色，"黄袍加身"便是赵匡胤陈桥兵变、黄袍加身开创宋朝的典故。《易经》中坤卦象征大地，"地势坤，君子以厚德载物"正是土属性的精神写照。历代龙袍均以明黄为主色，黄色与土属性的尊贵地位一脉相承。', '["文化","历史","黄袍"]', 15),
(16, '金', '颜色搭配', 'wuxing', '入门', '金属性穿搭色彩指南', '金属性人适合白色、银色和浅灰色系服饰。纯白衬衫干练利落，是职场经典单品；银灰色西装高级感满分，适合正式场合；浅灰色针织衫温柔知性适合日常。搭配建议：白色上衣配浅灰阔腿裤，简约大气；金属色配饰如银色项链、金色腕表可画龙点睛。避免过于暗沉的颜色，保持金属性的明亮锐利感。', '["颜色","搭配","白色"]', 16),
(17, '金', '材质推荐', 'wuxing', '入门', '金属性面料选择指南', '金属性与光滑、有质感的面料最为契合。真丝和缎面自带光泽感，如同金属般闪耀，适合重要场合。精纺羊毛面料挺括有型，是西装首选，呼应金属性的精致讲究。皮革也是上佳材质，皮衣的硬朗感完美契合金属性。夏季可选有光泽的天丝面料，垂感好又清凉。避免过于粗糙的面料，粗棉布和麻布与金属性相悖。', '["材质","面料","丝绸"]', 17),
(18, '金', '适合场景', 'wuxing', '入门', '金属性穿搭最佳场景', '金属性穿搭最适合商务谈判、高端晚宴和正式典礼。精致的白色衬衫搭配银灰西装在会议室中尽显专业气质；颁奖典礼上一袭白色礼服优雅出众。高端社交场合也很适合，简约而不简单的穿搭风格自带高级感。美术馆参观、古典音乐会、高端酒会等需要品位的场合，金属性的精致穿搭都能脱颖而出。', '["场景","商务","正式"]', 18),
(19, '金', '忌讳搭配', 'wuxing', '进阶', '金属性穿搭三大禁忌', '第一忌：大面积红色穿搭，红色属火，火克金会削弱金属性的锐气与贵气。如需红色可用小面积配饰点缀。第二忌：过于随意的穿搭风格，金属性讲究精致考究，松垮的运动装和邋遢的穿着与金属性格格不入。第三忌：廉价感面料，起球、褪色、皱巴巴的面料会严重拉低金属性穿搭的品质感，宁少勿滥。', '["禁忌","忌讳","火克金"]', 19),
(20, '金', '历史趣闻', 'wuxing', '精通', '白衣飘飘与金之素雅', '古人以白色对应金属性与秋天，"金秋"一词便由此而来。魏晋时期文人雅士尚白衣，竹林七贤着素袍抚琴论道，尽显超脱风骨。唐代科举放榜后，新科进士着白袍赴宴，称"白衣卿相"，白色象征纯洁与高贵。宋代士大夫亦爱白衣，朱熹曾言"白者，金之色也"。白色在传统文化中代表义气与果决，正是金的精神内核。', '["文化","历史","白衣"]', 20),
(21, '水', '颜色搭配', 'wuxing', '入门', '水属性穿搭色彩指南', '水属性人适合黑色、深蓝色和深灰色系服饰。经典黑色小礼服优雅百搭，任何场合都不会出错；藏蓝色大衣知性沉稳，是秋冬必备单品；深灰色卫衣休闲时尚两不误。搭配建议：黑色上衣配深蓝牛仔裤，低调又有型；或用宝蓝色围巾为全黑穿搭增加层次感。水属性的穿搭精髓在于深邃与神秘。', '["颜色","搭配","黑色"]', 21),
(22, '水', '材质推荐', 'wuxing', '入门', '水属性面料选择指南', '水属性适合柔软、垂坠感强的面料。真丝面料如水般流动贴合身体曲线，是首选材质。夏季雪纺和乔其纱轻盈飘逸，模拟水波的灵动感；秋冬选柔软针织和莫代尔面料，亲肤舒适如水流般温润。皮革中的软皮也很适合，软皮包袋和手套增添神秘气质。避免过于硬挺的面料，僵硬感与水的柔性特质相悖。', '["材质","面料","真丝"]', 22),
(23, '水', '适合场景', 'wuxing', '入门', '水属性穿搭最佳场景', '水属性穿搭最适合夜场活动、学术研讨和需要低调魅力的场合。深夜的鸡尾酒派对上，一袭黑色穿搭神秘优雅；学术论坛穿藏蓝色西装沉稳内敛有学者风范。水边活动如湖畔下午茶、海边漫步也很适合水属性穿搭，与环境融为一体。冥想课、瑜伽练习、图书馆自习等安静场合，深色穿搭都恰到好处。', '["场景","夜场","学术"]', 23),
(24, '水', '忌讳搭配', 'wuxing', '进阶', '水属性穿搭三大禁忌', '第一忌：大面积土黄色穿搭，黄色属土，土克水如同筑坝拦水，压制水属性的灵动与智慧。如需用黄色，建议小面积搭配。第二忌：过于蓬松膨胀的穿搭，水属性讲究流畅线条和贴合感，oversized廓形会破坏水的灵动特质。第三忌：过多暖色调叠加，水属阴性偏冷，橙红黄大面积堆砌与水的本质冲突，保持冷色调为主。', '["禁忌","忌讳","土克水"]', 24),
(25, '水', '历史趣闻', 'wuxing', '精通', '玄衣纁裳与水的智慧密码', '古人以黑色为水之色，称"玄色"。秦朝尚水德，始皇帝以黑色为尊，朝服旌旗皆用玄黑。《尚书》记载天子祭服"玄衣纁裳"，上玄下纁象征天与地、水与火的和谐。道家中老子以水喻道："上善若水，水善利万物而不争"，水的智慧在于柔能克刚、以退为进。黑色在中国服饰文化中始终代表庄重与深邃，是水的精神化身。', '["文化","历史","玄色"]', 25);
INSERT INTO wuxing_wiki (element, category, content_type, difficulty, title, content, tags, source, sort_order) VALUES
('通用', '周易基础', 'zhouyi', '入门', '什么是周易——群经之首', '《周易》是中国最古老的经典之一，被誉为"群经之首，大道之源"。它由《易经》和《易传》两部分组成。《易经》包含六十四卦的卦象、卦辞和爻辞，相传为周文王所演；《易传》是对《易经》的阐释，包含《系辞》《说卦》等十篇，相传为孔子所作。周易的核心思想是"变易"——万物皆在变化之中，掌握变化的规律便能趋吉避凶。', '["周易","入门","群经之首"]', '《周易》', 100),
('通用', '周易基础', 'zhouyi', '入门', '阴阳学说——万物对立统一', '阴阳是周易最基础的概念。阴阳并非两种对立的力量，而是同一事物的两个面：日为阳、月为阴；昼为阳、夜为阴；男为阳、女为阴。阴阳互根互用，阳极生阴，阴极生阳。《周易·系辞》云："一阴一阳之谓道"，阴阳的消长变化构成了宇宙万物的运行规律。在穿搭中，阴阳平衡体现在色彩的冷暖搭配、款式的刚柔并济。', '["阴阳","入门","对立统一"]', '《周易·系辞》', 101),
('通用', '周易基础', 'zhouyi', '进阶', '八卦入门——宇宙的八种基本形态', '八卦是周易的核心符号系统：乾（☰）为天、坤（☷）为地、震（☳）为雷、巽（☴）为风、坎（☵）为水、离（☲）为火、艮（☶）为山、兑（☱）为泽。每卦由三爻组成，阳爻"⚊"和阴爻"⚋"的不同排列代表不同的自然现象和属性。八卦两两相重形成六十四卦，涵盖世间万物的变化。在穿搭中，八卦可对应不同风格：乾卦刚健对应硬朗廓形，坤卦柔顺对应飘逸面料。', '["八卦","入门","八种形态"]', '《周易·说卦传》', 102),
('通用', '周易基础', 'zhouyi', '进阶', '六十四卦——人生处世的智慧指南', '六十四卦由八卦两两重叠而成，每卦六爻，共三百八十四爻。乾卦第一，讲述龙从"潜龙勿用"到"飞龙在天"再到"亢龙有悔"的完整发展过程，启示人们审时度势。坤卦第二，"地势坤，君子以厚德载物"，强调包容与承载的美德。屯卦讲创业之艰，蒙卦论教育启蒙，需卦谈等待时机……六十四卦如同一部人生百科全书，处处闪耀着古人的智慧光芒。', '["六十四卦","进阶","人生智慧"]', '《周易》', 103),
('通用', '周易基础', 'zhouyi', '精通', '天干地支——时间流转的密码', '天干有十：甲、乙、丙、丁、戊、己、庚、辛、壬、癸。地支有十二：子、丑、寅、卯、辰、巳、午、未、申、酉、戌、亥。天干地支组合形成六十甲子，用于纪年、纪月、纪日、纪时。每个天干地支都有对应的五行属性：甲乙属木，丙丁属火，戊己属土，庚辛属金，壬癸属水。了解天干地支，便能理解八字命理的基础，也是掌握每日运势变化的关键。', '["天干地支","精通","六十甲子"]', '《黄帝内经》《渊海子平》', 104),
('通用', '五行生克', 'zhouyi', '入门', '五行相生——万物循环的奥秘', '五行相生：木生火（钻木取火）、火生土（火烬成灰）、土生金（矿藏于土）、金生水（金熔为液）、水生木（水润草木）。相生关系如同母子关系，"生我"者为母，"我生"者为子。在穿搭中，相生配色最为和谐：木生火，绿色配红色生机勃勃；火生土，红色配黄色温暖明亮；土生金，黄色配白色典雅大方；金生水，白色配黑色简约高级；水生木，黑色配绿色深邃优雅。', '["五行","相生","循环"]', '《尚书·洪范》《黄帝内经》', 105),
('通用', '五行生克', 'zhouyi', '进阶', '五行相克——制衡之道的智慧', '五行相克：木克土（树根破土）、土克水（堤坝拦水）、水克火（水能灭火）、火克金（烈火熔金）、金克木（斧锯伐木）。相克并非坏事，而是维持平衡的必要力量。《黄帝内经》云："亢则害，承乃制"，过旺则有害，有制约才能平衡。穿搭中相克配色需谨慎：火克金，红白搭配可小面积点缀但不宜大面积对撞；水克火，蓝黑与红橙需要巧妙过渡才能和谐。', '["五行","相克","制衡"]', '《黄帝内经》', 106),
('通用', '五行生克', 'zhouyi', '精通', '五行乘侮——失衡的警示', '五行关系中，除了正常的生克，还有"相乘"和"相侮"两种异常状态。相乘是过度克制，如木气过旺过度克土，导致土虚；相侮是反向克制，如木气过旺反侮金，"木火刑金"便是此理。在穿搭中，理解乘侮关系有助于避免极端的搭配失衡：木属性过强（全身绿色）会压制土属性，金属性过强（全身白色）会伤及木属性。保持五行均衡是穿搭的最高境界。', '["五行","乘侮","均衡"]', '《黄帝内经·素问》', 107),
('通用', '节气穿搭', 'zhouyi', '入门', '二十四节气与穿衣智慧', '二十四节气是古人根据太阳运行规律制定的时间体系，每个节气约15天。立春阳气初生宜减衣，春分昼夜平分薄衫正好，夏至阳气最盛轻薄透气，秋分凉意渐起添件外套，冬至阴气最盛厚衣保暖。古人云"春捂秋冻"，春季不要急于减衣以防倒春寒，秋季适当冻一冻增强耐寒力。顺时而穿，不仅是养生之道，更是与自然和谐共处的智慧。', '["节气","二十四节气","时令"]', '《月令七十二候集解》', 108),
('通用', '节气穿搭', 'zhouyi', '进阶', '七十二候——节气中的微观变化', '每个节气又分三候，每候五天，全年共七十二候。如立春三候：一候东风解冻，二候蛰虫始振，三候鱼陟负冰。古人观察自然界的细微变化来指导农事和生活。在穿搭上，七十二候提醒我们关注天气的微妙变化：东风解冻时备一件薄外套，蛰虫始振时换掉厚重冬装，鱼陟负冰时仍需保暖。细微之处见真章，穿衣也是如此。', '["七十二候","微观","自然观察"]', '《逸周书·时训解》', 109),
('通用', '八字命理', 'zhouyi', '入门', '什么是八字——你的生命密码', '八字，又称四柱，由出生年、月、日、时的天干地支组成，共八个字。年柱代表祖上和童年，月柱代表父母和青年，日柱代表自己和配偶，时柱代表子女和晚年。日柱的天干称为"日元"或"日主"，代表命主本人。通过分析八字中五行的旺衰、生克关系，可以了解一个人的性格特质、运势走向和适合的穿衣风格。', '["八字","四柱","日元"]', '《渊海子平》《三命通会》', 110),
('通用', '八字命理', 'zhouyi', '进阶', '十神——八字中的角色关系', '十神是八字中描述五行关系的术语，以日元为中心，与其他干支的生克关系命名：生我者为正印/偏印，我生者为食神/伤官，克我者为正官/七杀，我克者为正财/偏财，同我者为比肩/劫财。十神各有含义：正官代表事业和规则，正财代表财富和稳定，食神代表才华和享受，七杀代表挑战和魄力。了解十神，便能读懂八字中的人生剧本。', '["十神","八字","角色关系"]', '《子平真诠》', 111),
('通用', '八字命理', 'zhouyi', '精通', '喜用神——你的穿搭增运密码', '喜用神是八字中最重要的概念之一。它是八字中最需要的五行元素，能平衡命局、补足不足。找到喜用神后，便可用对应的颜色、材质来增强运势：喜用木者多穿绿色，喜用火者多穿红色，喜用土者多穿黄色，喜用金者多穿白色，喜用水者多穿黑色。忌神则是需要避免的五行，穿搭中应尽量避免忌神对应的颜色和材质。顺益裳的核心功能，正是帮你找到喜用神并推荐对应穿搭。', '["喜用神","忌神","穿搭增运"]', '《滴天髓》《穷通宝鉴》', 112),
('通用', '历史趣闻', 'zhouyi', '入门', '文王演周易——从羑里到经典', '商朝末年，周文王姬昌被商纣王囚禁在羑里（今河南汤阴），在狱中他将伏羲的八卦推演为六十四卦，并撰写卦辞，这便是《周易》的起源。文王在困境中参悟天地变化之道，"困而不失其所"，将逆境转化为智慧。司马迁在《史记》中写道："文王拘而演周易"，一部经典诞生于困厄之中，其精神激励了无数后人。', '["历史","文王","羑里"]', '《史记·周本纪》', 113),
('通用', '历史趣闻', 'zhouyi', '进阶', '孔子与易传——儒家对周易的升华', '孔子晚年酷爱《周易》，"韦编三绝"——翻看竹简次数太多，穿竹简的牛皮绳断了三次。《论语》记载孔子说："加我数年，五十以学易，可以无大过矣。"孔子及其弟子为《周易》作传，即《易传》十篇，将周易从占卜之书提升为哲学经典。《系辞传》中"易有太极，是生两仪，两仪生四象，四象生八卦"的宇宙观，影响了中国两千多年的哲学思想。', '["历史","孔子","易传"]', '《史记·孔子世家》《论语》', 114),
('通用', '文化参考', 'zhouyi', '入门', '免责声明：文化参考，仅供娱乐', '本页面所有内容基于《周易》《黄帝内经》《尚书》等传统典籍和五行学说，旨在传播中国传统文化知识，帮助用户了解五行与穿搭的文化关联。五行穿搭知识属于文化参考范畴，不具有科学依据，仅供娱乐和学习参考。个人的穿搭选择应结合自身喜好、场合需求和实际天气情况。', '["免责声明","文化参考","仅供娱乐"]', '', 999);
